function parseCSV(content:string, expected:string[]){const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let index=0;index<content.length;index+=1){const char=content[index],next=content[index+1];if(char==='"'&&quoted&&next==='"'){cell+='"';index+=1;}else if(char==='"'){quoted=!quoted;}else if(char===','&&!quoted){row.push(cell.trim());cell='';}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')index+=1;row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row);row=[];cell='';}else{cell+=char;}}if(cell||row.length){row.push(cell.trim());rows.push(row);}if(rows.length<2||rows[0].join(',')!==expected.join(','))throw new Error(`CSV must use: ${expected.join(',')}`);if(rows.slice(1).some(values=>values.length!==expected.length))throw new Error('CSV contains a row with an invalid number of columns.');return rows.slice(1);}
function filterMovements(movements: Movement[], query: string, jql: boolean) {
  const normalized = query.trim().toLowerCase();
  const haystack = (movement: Movement) => `${movement.description ?? ''} ${movement.categoryName ?? ''} ${movement.currency ?? ''} ${movement.direction ?? ''} ${movement.status ?? ''} ${movement.occurredOn ?? ''}`.toLowerCase();
  if (!normalized) return movements;
  if (!jql) return movements.filter(movement => haystack(movement).includes(normalized));
  const groups = normalized.split(/\s+or\s+/i);
  return movements.filter(movement => groups.some(group => {
    const terms = (group.match(/(?:\w+:)?"[^"]*"|\S+/g) ?? []).filter(term => term.toLowerCase() !== 'and');
    return terms.every(term => {
      const [field, ...parts] = term.split(':');
      const value = parts.join(':');
      if (!value) return haystack(movement).includes(field);
      const text = value.replace(/^"|"$/g, '').toLowerCase();
      if (field === 'type' || field === 'direction') return movement.direction === text;
      if (field === 'category') return (movement.categoryName ?? '').toLowerCase().includes(text);
      if (field === 'currency') return movement.currency?.toLowerCase() === text;
      if (field === 'status') return movement.status === text;
		if (field === 'date') return movement.occurredOn === text;
		if (field === 'month') return movement.occurredOn.startsWith(text);
      if (field === 'from') return movement.occurredOn >= text;
      if (field === 'to') return movement.occurredOn <= text;
      return haystack(movement).includes(term);
    });
  }));
}
type FilterPill = { id: string; field: string; label: string; query: string; connector: 'AND' | 'OR' };
function MovementFilterBuilder({movements,query,setQuery,language,t,resetKey,savedFilters,onSave,onRename,onDuplicate,onDelete}:{movements:Movement[];query:string;setQuery:(value:string)=>void;language:Lang;t:Copy;resetKey:number;savedFilters:SavedFilter[];onSave:(name:string,query:string)=>void;onRename:(filter:SavedFilter,name:string)=>void;onDuplicate:(filter:SavedFilter)=>void;onDelete:(id:string)=>void}) {
  const [pills,setPills]=useState<FilterPill[]>([]);
  const [connector,setConnector]=useState<'AND'|'OR'>('AND');
  const [menu,setMenu]=useState<string>('');
  const [exactDate,setExactDate]=useState('');
  const [month,setMonth]=useState('');
  const [from,setFrom]=useState('');
  const [to,setTo]=useState('');
  const [showText,setShowText]=useState(false);
  const expression=(values:FilterPill[])=>values.map((pill,index)=>`${index ? `${pill.connector} ` : ''}${pill.query}`).join(' ');
  const scopeFor=(field:string)=>filterMovements(movements,expression(pills.filter(pill=>pill.field!==field)),true);
  const unique=(field:'direction'|'categoryName'|'currency'|'status')=>[...new Set(scopeFor(field==='direction'?'type':field==='categoryName'?'category':field).map(item=>item[field]).filter(Boolean))].sort();
  const add=(field:string,label:string,value:string)=>{
    const queryValue=field==='category'?`category:"${value}"`:`${field}:${value}`;
    const next={id:`${field}:${value}:${Date.now()}`,field,label,query:queryValue,connector};
    setPills(current=>{
      let updated:FilterPill[];
      if(connector==='AND'){
        const index=current.findIndex(item=>item.field===field);
        if(index>=0){const copy=[...current];copy[index]={...next,connector:copy[index].connector};updated=copy;setQuery(expression(updated));return updated;}
      }
      if(current.some(item=>item.query===queryValue))return current;
      updated=[...current,next];setQuery(expression(updated));return updated;
    });
    setMenu('');
  };
  const addRange=()=>{if(!from||!to||from>to)return;const label=`${from} → ${to}`;const next={id:`range:${from}:${to}`,field:'range',label,query:`from:${from} AND to:${to}`,connector};setPills(current=>{const updated=[...current.filter(item=>item.field!=='range'),next];setQuery(expression(updated));return updated;});setFrom('');setTo('');};
  const remove=(id:string)=>setPills(current=>{const updated=current.filter(item=>item.id!==id);setQuery(expression(updated));return updated;});
  useEffect(()=>{setPills([]);setMenu('');},[resetKey]);
  const menuValues=(key:string)=>key==='type'?unique('direction').map(value=>({value,label:value==='income'?t.income:t.expense})):key==='category'?unique('categoryName').map(value=>({value,label:value})):key==='currency'?unique('currency').map(value=>({value,label:value})):unique('status').map(value=>({value,label:value==='active'?t.active:t.voided}));
  const title=(key:string)=>key==='type'?(language==='es'?'Tipo':'Type'):key==='category'?(language==='es'?'Categoría':'Category'):key==='currency'?t.currency:t.status;
  return <><div className="filter-pills" aria-label={language==='es'?'Filtros aplicados':'Applied filters'}>{pills.length?pills.map(pill=><span className="filter-pill" key={pill.id}>{pill.connector} · {pill.label}<button onClick={()=>remove(pill.id)} aria-label={`${language==='es'?'Quitar':'Remove'} ${pill.label}`}>×</button></span>):<span className="filter-empty">{language==='es'?'Elegí un filtro para comenzar.':'Choose a filter to begin.'}</span>}</div><div className="filter-assistant"><span>{language==='es'?'Construir consulta:':'Build query:'}</span>{(['AND','OR'] as const).map(value=><button key={value} disabled={!pills.length} className={`secondary ${connector===value?'selected':''}`} onClick={()=>setConnector(value)}>{value}</button>)}{['type','category','currency','status'].map(key=>{const options=menuValues(key);return <div className="filter-select" key={key}><button className="secondary" disabled={!options.length} onClick={()=>setMenu(menu===key?'':key)} aria-expanded={menu===key}>{title(key)} ▾</button>{menu===key&&<div className="filter-menu">{options.map(option=><button key={option.value} onClick={()=>add(key,`${title(key)}: ${option.label}`,option.value)}>{option.label}</button>)}</div>}</div>})}</div><div className="date-filter-row"><MaterialDateField value={exactDate} onChange={value=>{setExactDate(value);if(value)add('date',`${language==='es'?'Fecha':'Date'}: ${value}`,value);}} label={language==='es'?'Fecha':'Date'} language={language}/><MaterialDateField value={month} onChange={value=>{setMonth(value);if(value)add('month',`${language==='es'?'Mes':'Month'}: ${value}`,value);}} label={language==='es'?'Mes':'Month'} language={language} monthOnly/><MaterialDateField value={from} onChange={setFrom} label={language==='es'?'Desde':'From'} language={language}/><MaterialDateField value={to} onChange={setTo} label={language==='es'?'Hasta':'To'} language={language}/><button className="secondary" disabled={!from||!to||from>to} onClick={addRange}>{language==='es'?'Aplicar rango':'Apply range'}</button></div><div className="query-tools"><button className="secondary" onClick={()=>setShowText(value=>!value)}>{showText?(language==='es'?'Ocultar texto':'Hide text'):(language==='es'?'Ver texto de consulta':'Show query text')}</button><button className="secondary" disabled={!query} onClick={()=>navigator.clipboard?.writeText(query)}>{language==='es'?'Copiar consulta':'Copy query'}</button><button className="secondary" disabled={!query} onClick={()=>{const name=window.prompt(language==='es'?'Nombre del filtro':'Filter name');if(name?.trim())onSave(name,query);}}>{language==='es'?'Guardar filtro':'Save filter'}</button></div>{showText&&<textarea className="jql-filter" value={query} onChange={event=>{setPills([]);setQuery(event.target.value);}} placeholder="type:expense AND category:&quot;alquiler&quot;" aria-label={language==='es'?'Consulta avanzada':'Advanced query'}/>}<div className="saved-filters"><strong>{language==='es'?'Filtros guardados':'Saved filters'}</strong>{savedFilters.length?savedFilters.map(filter=><div key={filter.id}><button className="secondary" onClick={()=>{setPills([]);setQuery(filter.query);}}>{filter.name}</button><button className="secondary" onClick={()=>{const name=window.prompt(language==='es'?'Nuevo nombre':'New name',filter.name);if(name?.trim())onRename(filter,name);}}>{language==='es'?'Renombrar':'Rename'}</button><button className="secondary" onClick={()=>onDuplicate(filter)}>{language==='es'?'Duplicar':'Duplicate'}</button><button className="secondary" onClick={()=>onDelete(filter.id)}>{language==='es'?'Eliminar':'Delete'}</button></div>):<small>{language==='es'?'Todavía no hay filtros guardados.':'No saved filters yet.'}</small>}</div><small>{language==='es'?'Las opciones disponibles se calculan sobre los movimientos que aún cumplen los filtros aplicados.':'Available options are calculated from movements that still satisfy the applied filters.'}</small></>;
}
function tabIcon(tab:Tab){const props={fontSize:'small' as const};return ({record:<PlaylistAddOutlined {...props}/>,movements:<ReceiptLongOutlined {...props}/>,accounts:<AccountBalanceWalletOutlined {...props}/>,categories:<CategoryOutlined {...props}/>,analytics:<InsightsOutlined {...props}/>,users:<GroupOutlined {...props}/>,requests:<AssignmentTurnedInOutlined {...props}/>,audit:<HistoryOutlined {...props}/>,settings:<SettingsOutlined {...props}/>})[tab];}
function Dashboard({token,user,language,setLanguage,colorMode,setColorMode,accent,setAccent,typography,setTypography,allowLogger,setAllowLogger,logout,onPasswordChanged}:{token:string;user:User;language:Lang;setLanguage:(v:Lang)=>void;colorMode:ColorMode;setColorMode:(value:ColorMode)=>void;accent:AccentPalette;setAccent:(value:AccentPalette)=>void;typography:TypographyFamily;setTypography:(value:TypographyFamily)=>void;allowLogger:boolean;setAllowLogger:(value:boolean)=>void;logout:()=>void;onPasswordChanged:()=>void}){
  const t=copy[language], [tab,setTab]=useState<Tab>('record'),[accounts,setAccounts]=useState<Account[]>([]),[categories,setCategories]=useState<Category[]>([]),[movements,setMovements]=useState<Movement[]>([]),[users,setUsers]=useState<User[]>([]),[requests,setRequests]=useState<DeletionRequest[]>([]),[auditEvents,setAuditEvents]=useState<AuditEvent[]>([]),[savedFilters,setSavedFilters]=useState<SavedFilter[]>([]),[error,setError]=useState(''),[notice,setNotice]=useState(''),[hidden,setHidden]=useState(true),[movementDate,setMovementDate]=useState(currentLocalDate),[movementCategoryId,setMovementCategoryId]=useState(''),[movementDirection,setMovementDirection]=useState<'income'|'expense'>('expense'),[movementQuery,setMovementQuery]=useState(''),[filterReset,setFilterReset]=useState(0),[jqlMode,setJqlMode]=useState(false),[voidReason,setVoidReason]=useState(''),[categoryReplacement,setCategoryReplacement]=useState(''),[accountReplacement,setAccountReplacement]=useState(''),[pendingAction,setPendingAction]=useState<{kind:'accounts'|'categories'|'transactions'|'users';id:string;action:'activate'|'deactivate'|'void'|'delete'}|null>(null),[editing,setEditing]=useState<{kind:'accounts'|'categories';item:Account|Category}|null>(null),[passwordOpen,setPasswordOpen]=useState(Boolean(user.mustChangePassword));
  const load=async()=>{try{const elevated=user.role==='administrator'||user.role==='manager';const [a,c,m,filters]=await Promise.all([request<Account[]>(`/v1/accounts${elevated?'?include_inactive=true':''}`,token),request<Category[]>(`/v1/categories${elevated?'?include_inactive=true':''}`,token),request<Movement[]>('/v1/transactions',token),request<SavedFilter[]>('/v1/saved-filters',token)]);setAccounts(a??[]);setCategories(c??[]);setMovements(m??[]);setSavedFilters(filters??[]);setRequests(await request<DeletionRequest[]>('/v1/deletion-requests',token));if(user.role==='administrator')setUsers(await request<User[]>('/v1/users',token));if(elevated)setAuditEvents(await request<AuditEvent[]>('/v1/audit-events',token));}catch(e){setError((e as Error).message);}};
  useEffect(()=>{load();},[]);
  useEffect(()=>{if(!notice&&!error)return;const timer=window.setTimeout(()=>{setNotice('');setError('');},10_000);return()=>window.clearTimeout(timer);},[notice,error]);
  const auditPreference=(kind:'appearance'|'language',before:Record<string,string>,after:Record<string,string>)=>{void request<void>('/v1/audit-events/preferences',token,'POST',{kind,before,after}).then(()=>{if(user.role!=='operator')void load();}).catch(error=>setError((error as Error).message));};
  const changeColorMode=(value:ColorMode)=>{if(value===colorMode)return;const nextAccent=(localStorage.getItem(`fluxeando-accent-${value}`) as AccentPalette)||'graphite';auditPreference('appearance',{mode:colorMode,palette:accent},{mode:value,palette:nextAccent});setColorMode(value);};
  const changeAccent=(value:AccentPalette)=>{if(value===accent)return;auditPreference('appearance',{mode:colorMode,palette:accent},{mode:colorMode,palette:value});setAccent(value);};
  const changeTypography=(value:TypographyFamily)=>{if(value===typography)return;auditPreference('appearance',{typography},{typography:value});setTypography(value);};
  const changeLanguage=(value:Lang)=>{if(value===language)return;auditPreference('language',{language},{language:value});setLanguage(value);};
  const post=(path:string,body:(f:FormData)=>unknown,message=t.savedNotice)=>async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;setError('');try{await request(path,token,'POST',body(new FormData(form)));form.reset();await load();setNotice(message);}catch(x){setError((x as Error).message);}};
  const edit=(kind:'accounts'|'categories',item:Account|Category)=>setEditing({kind,item});
  const saveEdit=async(kind:'accounts'|'categories',item:Account|Category,name:string,value:string)=>{try{await request(`/v1/${kind}/${item.id}`,token,'PUT',kind==='accounts'?{name,type:value}:{name,direction:value});await load();setNotice(t.savedNotice);setEditing(null);}catch(x){setError((x as Error).message);}};
  const deactivate=(kind:'accounts'|'categories',id:string)=>setPendingAction({kind,id,action:'deactivate'});
  const requestVoid=(id:string)=>setPendingAction({kind:'transactions',id,action:'void'});
  const userAction=(id:string,action:'activate'|'deactivate'|'delete')=>{if(action==='delete'&&users.find(item=>item.id===id)?.canDelete===false)return;setPendingAction({kind:'users',id,action});};
  const accountAction=(id:string,action:'activate'|'deactivate'|'delete')=>setPendingAction({kind:'accounts',id,action});
  const categoryAction=(id:string,action:'activate'|'deactivate'|'delete')=>setPendingAction({kind:'categories',id,action});
  const bulkAction=async(kind:'accounts'|'categories'|'users',ids:string[],action:'activate'|'deactivate')=>{try{if(!ids.length)return;await Promise.all(ids.map(id=>request(`/v1/${kind}/${id}/${action}`,token,'POST')));await load();setNotice(language==='es'?`${ids.length} elementos actualizados.`:`${ids.length} items updated.`);}catch(x){setError((x as Error).message);}};
  const confirmAction=async()=>{if(!pendingAction)return;try{const {kind,id,action}=pendingAction;if(kind==='transactions'){await request(`/v1/transactions/${id}/void`,token,'POST',{reason:voidReason});setNotice(user.role==='operator'?(language==='es'?'Solicitud de anulación enviada.':'Void request submitted.'):t.voidedNotice);setVoidReason('');}else if(kind==='users'||kind==='accounts'){await request(`/v1/${kind}/${id}${action==='activate'?'/activate':action==='deactivate'?'/deactivate':''}`,token,action==='delete'?'DELETE':'POST',kind==='accounts'&&action==='delete'?{replacementAccountId:accountReplacement}:undefined);setNotice(action==='delete'?(language==='es'?'Elemento eliminado.':'Item deleted.'):(action==='activate'?(language==='es'?'Elemento activado.':'Item activated.'):(language==='es'?'Elemento desactivado.':'Item deactivated.')));setAccountReplacement('');}else if(action==='activate'){await request(`/v1/categories/${id}/activate`,token,'POST');setNotice(language==='es'?'Elemento activado.':'Item activated.');}else{await request(`/v1/${kind}/${id}/deactivate`,token,'POST',{replacementCategoryId:categoryReplacement});setNotice(t.deactivatedNotice);setCategoryReplacement('');}await load();}catch(x){setError((x as Error).message);}finally{setPendingAction(null);}};
  const resolveRequest=async(id:string,decision:'approve'|'reject')=>{try{await request(`/v1/deletion-requests/${id}/${decision}`,token,'POST');await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const cancelRequest=async(id:string)=>{try{await request(`/v1/deletion-requests/${id}/cancel`,token,'POST');await load();setNotice(language==='es'?'Solicitud cancelada.':'Request cancelled.');}catch(x){setError((x as Error).message);}};
  const exportCSV=async(path:string,name:string)=>{try{downloadCSV(name,await request<string>(path,token));}catch(x){setError((x as Error).message);}};
  const importCategoriesCSV=async(file:File)=>{try{const rows=parseCSV(await file.text(),['name','direction']);for(const [name,direction] of rows)await request('/v1/categories',token,'POST',{name,direction});await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const importMovementsCSV=async(file:File)=>{try{const rows=parseCSV(await file.text(),['account_name','category_name','direction','amount_minor','currency','description','occurred_on']);const accountIDs=new Map(accounts.filter(item=>item.active).map(item=>[item.name,item.id]));const categoryIDs=new Map(categories.map(item=>[item.name,item.id]));for(const row of rows){const accountName=row[0];if(accountName&&!accountIDs.has(accountName)){try{await request('/v1/accounts',token,'POST',{name:accountName,type:'cash'});}catch(error){if(!(error instanceof Error)||!error.message.includes('UNIQUE constraint failed: accounts.name'))throw error;}accountIDs.set(accountName,'');}const direction=row[2];const categoryName=row[1];if(categoryName&&!categoryIDs.has(categoryName)){try{await request('/v1/categories',token,'POST',{name:categoryName,direction});}catch(error){if(!(error instanceof Error)||!error.message.includes('UNIQUE constraint failed: categories.name'))throw error;}categoryIDs.set(categoryName,'');}}const elevated=user.role==='administrator'||user.role==='manager';const [latestAccounts,latestCategories]=await Promise.all([request<Account[]>(`/v1/accounts${elevated?'?include_inactive=true':''}`,token),request<Category[]>('/v1/categories',token)]);latestAccounts.filter(item=>item.active).forEach(item=>accountIDs.set(item.name,item.id));latestCategories.forEach(item=>categoryIDs.set(item.name,item.id));const values=rows.map((row,index)=>{const amountMinor=Number(row[3]);if(!Number.isSafeInteger(amountMinor)||amountMinor<=0)throw new Error(`Row ${index+2}: amount_minor must be a positive integer.`);const accountId=accountIDs.get(row[0]);if(!accountId)throw new Error(`Row ${index+2}: account ${row[0]} is inactive or could not be created.`);const categoryId=row[1]?categoryIDs.get(row[1]):'';if(row[1]&&!categoryId)throw new Error(`Row ${index+2}: category ${row[1]} could not be created.`);return {accountId,categoryId,direction:row[2],amountMinor,currency:row[4].toUpperCase(),description:row[5],occurredOn:row[6]};});for(const value of values)await request('/v1/transactions',token,'POST',value);await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const saveFilter=async(name:string,query:string)=>{try{await request('/v1/saved-filters',token,'POST',{name,query});await load();setNotice(language==='es'?'Filtro guardado.':'Filter saved.');}catch(x){setError((x as Error).message);}};
  const renameFilter=async(filter:SavedFilter,name:string)=>{try{await request(`/v1/saved-filters/${filter.id}`,token,'PUT',{name,query:filter.query});await load();setNotice(t.savedNotice);}catch(x){setError((x as Error).message);}};
  const duplicateFilter=async(filter:SavedFilter)=>saveFilter(`${filter.name} (${language==='es'?'copia':'copy'})`,filter.query);
  const deleteFilter=async(id:string)=>{try{await request(`/v1/saved-filters/${id}`,token,'DELETE');await load();setNotice(language==='es'?'Filtro eliminado.':'Filter deleted.');}catch(x){setError((x as Error).message);}};
  const resetUserPassword=async(id:string)=>{const generated=generatePassword();try{await request(`/v1/users/${id}/password`,token,'POST',{newPassword:generated});await copySecret(generated);downloadCSV(`fluxeando-password-${exportTimestamp()}.csv`,`display_name,email,password,generated_at\n${csvCell(users.find(item=>item.id===id)?.displayName??'')},${csvCell(users.find(item=>item.id===id)?.email??'')},${csvCell(generated)},${csvCell(new Date().toISOString())}\n`);await load();setNotice(language==='es'?'Clave restablecida, copiada al portapapeles y exportada a CSV.':'Password reset, copied to clipboard, and exported to CSV.');}catch(x){setError((x as Error).message);}};
  const selectMovementCategory=(categoryId:string)=>{setMovementCategoryId(categoryId);const direction=categories.find(category=>category.id===categoryId)?.direction;if(direction==='income'||direction==='expense')setMovementDirection(direction);};
  const labels:Record<Tab,string>={record:t.record,movements:t.movements,accounts:t.accounts,categories:t.categories,analytics:t.analytics,users:language==='es'?'Usuarios':'Users',requests:language==='es'?'Solicitudes':'Requests',audit:language==='es'?'Auditoría':'Audit',settings:language==='es'?'Configuración':'Settings'};
  const availableTabs=(Object.keys(labels) as Tab[]).filter(k=>user.role!=='operator'||k==='record'||k==='movements'||k==='categories'||k==='requests').filter(k=>user.role==='administrator'||k!=='users').filter(k=>user.role!=='operator'||k!=='audit');
  const visibleMovements=useMemo(()=>filterMovements(movements,movementQuery,jqlMode),[movements,movementQuery,jqlMode]);
  return <main className={`app-shell ${colorMode}`} style={materialVariables(materialSchemes[accent][colorMode])}><aside className="app-sidebar"><div className="sidebar-brand"><span className="sidebar-logo"><img src={fluxeandoIcon} alt="FLUXeando"/></span><span className="fluxeando-wordmark"><strong>FLUX</strong><span>eando</span></span></div><nav className="tabs">{availableTabs.map(k=><button key={k} className={tab===k?'selected':''} onClick={()=>setTab(k)}>{tabIcon(k)}<span>{labels[k]}</span></button>)}</nav><small className="sidebar-meta">v{APP_VERSION} · Local</small></aside><section className="app-content"><header><div><p className="eyebrow"><strong>cash</strong>FLOW</p><h1>{labels[tab]}</h1><small>{user.displayName} · {user.role}</small></div><div className="header-actions"><ThemeSwitch language={language} colorMode={colorMode} setColorMode={changeColorMode}/><Language language={language} setLanguage={changeLanguage}/><Button variant="outlined" color="inherit" onClick={logout} startIcon={<LogoutOutlined/>}>{t.signOut}</Button></div></header>{error&&<p className="error">{error}</p>}{notice&&<p className="notice">{notice}</p>}
  {tab==='record'&&<section className="card record-card"><h2>{t.record}</h2><form className="transaction" onSubmit={post('/v1/transactions',f=>({accountId:f.get('accountId'),categoryId:f.get('categoryId'),direction:f.get('direction'),amountMinor:Math.round(Number(f.get('amount'))*100),currency:String(f.get('currency')).toUpperCase(),description:f.get('description'),occurredOn:f.get('occurredOn')}))}><select className="transaction-account" name="accountId" required><option value="">{t.accounts}</option>{accounts.filter(a=>a.active).map(a=><option key={a.id} value={a.id}>{a.name}</option>)}</select><select className="transaction-category" name="categoryId" value={movementCategoryId} onChange={event=>selectMovementCategory(event.target.value)}><option value="">{t.categories}</option>{categories.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><select className="transaction-direction" name="direction" value={movementDirection} onChange={event=>setMovementDirection(event.target.value as 'income'|'expense')}><option value="expense">{t.expense}</option><option value="income">{t.income}</option></select><MoneyInput placeholder={t.amount}/><select className="transaction-currency" name="currency" defaultValue="ARS" aria-label={t.currency}><option value="ARS">ARS · Peso argentino</option><option value="USD">USD · US dollar</option><option value="EUR">EUR · Euro</option><option value="BRL">BRL · Real brasileño</option></select><MaterialDateField className="transaction-date" value={movementDate} onChange={setMovementDate} label={t.date} language={language}/><input name="occurredOn" type="hidden" value={movementDate}/><input className="transaction-description" name="description" placeholder={t.description}/><button className="transaction-save">{t.save}</button></form></section>}
  {tab==='movements'&&<section className="card"><div className="section-head"><h2>{t.movements}</h2><FormControlLabel label={hidden?t.show:t.hide} control={<Switch checked={!hidden} onChange={event=>setHidden(!event.target.checked)} inputProps={{'aria-label':hidden?t.show:t.hide}}/>}/></div><div className="filter-mode"><button className={!jqlMode?'selected':'secondary'} aria-pressed={!jqlMode} onClick={()=>setJqlMode(false)}>{language==='es'?'Búsqueda normal':'Normal search'}</button><button className={jqlMode?'selected':'secondary'} aria-pressed={jqlMode} onClick={()=>setJqlMode(true)}>{language==='es'?'Consulta avanzada':'Advanced query'}</button><button className="secondary" onClick={()=>{setMovementQuery('');setFilterReset(value=>value+1);}}>{language==='es'?'Limpiar':'Clear'}</button></div>{jqlMode?<MovementFilterBuilder key={filterReset} movements={movements} query={movementQuery} setQuery={setMovementQuery} language={language} t={t} resetKey={filterReset} savedFilters={savedFilters} onSave={saveFilter} onRename={renameFilter} onDuplicate={duplicateFilter} onDelete={deleteFilter}/>:<input className="movement-search" value={movementQuery} onChange={e=>setMovementQuery(e.target.value)} placeholder={language==='es'?'Buscar por descripción, categoría, moneda, tipo o estado':'Search description, category, currency, type, or status'}/>}<CsvActions onTemplate={()=>downloadCSV('cashflow-movements-template.csv',movementTemplateCSV)} onImport={importMovementsCSV} onExport={user.role==='operator'?undefined:()=>exportCSV('/v1/exports/transactions.csv',`cashflow-movements-${exportTimestamp()}.csv`)}/><table><thead><tr><th>{t.date}</th><th>{t.type}</th><th>{t.categories}</th><th>{t.currency}</th><th>{t.amount}</th><th>{t.description}</th><th>{t.status}</th><th/></tr></thead><tbody>{visibleMovements.map(m=><tr key={m.id} className={m.status==='voided'?'voided-row':''}><td>{m.occurredOn}</td><td>{m.direction==='income'?t.income:t.expense}</td><td>{m.categoryName||'—'}</td><td>{m.currency}</td><td><Amount amount={m.amountMinor} hidden={hidden}/></td><td>{m.description}</td><td>{m.status==='active'?t.active:t.voided}</td><td>{m.status==='active'&&<button className="secondary" onClick={()=>requestVoid(m.id)}>{user.role==='operator'?(language==='es'?'Solicitar anulación':'Request void'):t.void}</button>}</td></tr>)}</tbody></table></section>}
  {tab==='accounts'&&<Management t={t} kind="accounts" items={accounts} submit={post('/v1/accounts',f=>({name:f.get('name'),type:f.get('type')}))} edit={v=>edit('accounts',v)} deactivate={id=>deactivate('accounts',id)} onAccountAction={accountAction} onBulk={(ids,action)=>bulkAction('accounts',ids,action)}/>}
  {tab==='categories'&&user.role==='operator'&&<section className="card"><h2>{t.categories}</h2><form className="inline" onSubmit={post('/v1/categories',f=>({name:f.get('name'),direction:f.get('direction')}))}><input name="name" placeholder={t.categoryName} required/><select name="direction"><option value="expense">{t.expense}</option><option value="income">{t.income}</option><option value="both">{language==='es'?'Ambos':'Both'}</option></select><button>{t.add}</button></form></section>}
  {tab==='categories'&&user.role!=='operator'&&<Management t={t} kind="categories" items={categories} submit={post('/v1/categories',f=>({name:f.get('name'),direction:f.get('direction')}))} edit={v=>edit('categories',v)} deactivate={id=>deactivate('categories',id)} onCategoryAction={categoryAction} onBulk={(ids,action)=>bulkAction('categories',ids,action)} csv={{onTemplate:()=>downloadCSV('cashflow-categories-template.csv',categoryTemplateCSV),onImport:importCategoriesCSV}}/>}
  {tab==='analytics'&&<div className="analytics-shell"><div className="analytics-actions"><Switch checked={!hidden} onChange={event=>setHidden(!event.target.checked)} inputProps={{'aria-label':hidden?'Mostrar montos':'Ocultar montos'}}/><button className="secondary" onClick={()=>window.print()}>Exportar PDF</button></div><AnalyticsDashboard movements={movements} accounts={accounts} hidden={hidden}/></div>}
  {tab==='users'&&user.role==='administrator'&&<UserManagement users={users} currentUserId={user.id} submit={post('/v1/users',f=>({email:f.get('email'),displayName:f.get('displayName'),password:f.get('password'),role:f.get('role'),forcePasswordChange:f.get('forcePasswordChange')==='true'}))} onAction={userAction} onBulk={(ids,action)=>bulkAction('users',ids,action)} onResetPassword={resetUserPassword} language={language}/>}
  {tab==='requests'&&<DeletionRequests requests={requests} resolve={resolveRequest} cancel={cancelRequest} canResolve={user.role!=='operator'} language={language}/>}
  {tab==='audit'&&user.role!=='operator'&&<AuditTrail events={auditEvents} language={language}/>}
  {tab==='settings'&&<><AppearanceSettings language={language} colorMode={colorMode} accent={accent} onAccentChange={changeAccent} typography={typography} onTypographyChange={changeTypography}/><Card className="material-card settings-card" elevation={0}><CardContent><Stack spacing={2}><Typography component="h2" variant="h5">{language==='es'?'Opciones':'Options'}</Typography><FormControlLabel label={language==='es'?'Permitir vista de logger':'Allow logger view'} control={<Switch checked={allowLogger} onChange={event=>setAllowLogger(event.target.checked)} inputProps={{'aria-label':language==='es'?'Permitir vista de logger':'Allow logger view'}}/>}/><Button onClick={()=>setPasswordOpen(true)}>{language==='es'?'Cambiar mi clave':'Change my password'}</Button></Stack></CardContent></Card><Card className="material-card settings-card storage-card" elevation={0}><CardContent><StorageSettings language={language}/></CardContent></Card></>}
  {pendingAction&&<div className="modal-backdrop" role="presentation"><section className="modal" role="dialog" aria-modal="true" aria-labelledby="confirm-action-title"><h2 id="confirm-action-title">{pendingAction.action==='void'?(language==='es'?'¿Confirmar anulación?':'Confirm void?'):pendingAction.action==='delete'?(language==='es'?'¿Eliminar este elemento?':'Delete this item?'):pendingAction.action==='activate'?(language==='es'?'¿Activar este elemento?':'Activate this item?'):(language==='es'?'¿Desactivar este elemento?':'Deactivate this item?')}</h2><p>{pendingAction.action==='void'?(user.role==='operator'?(language==='es'?'Se creará una solicitud para que un administrador o gestor la apruebe.':'A request will be created for an administrator or manager to approve.'):(language==='es'?'El movimiento quedará anulado y se conservará en el historial.':'The movement will be voided and retained in history.')):pendingAction.action==='delete'?(language==='es'?'La eliminación es permanente. Si existen movimientos, elegí una cuenta destino para migrarlos.':'Deletion is permanent. If movements exist, choose a destination account to migrate them.'):(language==='es'?'Se actualizará el estado del elemento.':'The item status will be updated.')}</p>{pendingAction.action==='void'&&user.role==='operator'&&<textarea value={voidReason} onChange={e=>setVoidReason(e.target.value)} placeholder={language==='es'?'Motivo de la solicitud':'Request reason'} required/>}{pendingAction.kind==='categories'&&pendingAction.action==='deactivate'&&<label>{language==='es'?'Si la categoría tiene movimientos, migrarlos a:':'If the category has movements, migrate them to:'}<select value={categoryReplacement} onChange={e=>setCategoryReplacement(e.target.value)}><option value="">{language==='es'?'Seleccionar si corresponde':'Select if needed'}</option>{categories.filter(category=>category.active&&category.id!==pendingAction.id).map(category=><option key={category.id} value={category.id}>{category.name}</option>)}</select></label>}{pendingAction.kind==='accounts'&&pendingAction.action==='delete'&&<label>{language==='es'?'Si la cuenta tiene movimientos, migrarlos a:':'If the account has movements, migrate them to:'}<select value={accountReplacement} onChange={e=>setAccountReplacement(e.target.value)}><option value="">{language==='es'?'Seleccionar si corresponde':'Select if needed'}</option>{accounts.filter(account=>account.active&&account.id!==pendingAction.id).map(account=><option key={account.id} value={account.id}>{account.name}</option>)}</select></label>}<div className="modal-actions"><button className="secondary" onClick={()=>{setPendingAction(null);setVoidReason('');setCategoryReplacement('');setAccountReplacement('');}}>{language==='es'?'Cancelar':'Cancel'}</button><button disabled={pendingAction.action==='void'&&user.role==='operator'&&!voidReason.trim()} onClick={confirmAction}>{pendingAction.action==='void'?(language==='es'?'Confirmar':'Confirm'):pendingAction.action==='delete'?(language==='es'?'Eliminar':'Delete'):pendingAction.action==='activate'?(language==='es'?'Activar':'Activate'):(language==='es'?'Desactivar':'Deactivate')}</button></div></section></div>}
  {editing&&<EditModal kind={editing.kind} item={editing.item} language={language} onClose={()=>setEditing(null)} onSave={saveEdit}/>}<PasswordChangeModal token={token} language={language} forced={Boolean(user.mustChangePassword)} open={passwordOpen} onClose={()=>setPasswordOpen(false)} onDone={()=>{setPasswordOpen(false);onPasswordChanged();}} onError={setError}/></section></main>;
}
function EditModal({kind,item,language,onClose,onSave}:{kind:'accounts'|'categories';item:Account|Category;language:Lang;onClose:()=>void;onSave:(kind:'accounts'|'categories',item:Account|Category,name:string,value:string)=>void}){const [name,setName]=useState(item.name);const [value,setValue]=useState('type'in item?item.type:item.direction);const accounts=kind==='accounts';const selectLabel=accounts?(language==='es'?'Tipo':'Type'):(language==='es'?'Tipo de categoría':'Category type');const submit=(event:FormEvent)=>{event.preventDefault();if(name.trim())onSave(kind,item,name.trim(),value);};return <div className="modal-backdrop"><form className="modal edit-modal" role="dialog" aria-modal="true" aria-labelledby="edit-modal-title" onSubmit={submit}><h2 id="edit-modal-title">{language==='es'?(accounts?'Editar cuenta':'Editar categoría'):(accounts?'Edit account':'Edit category')}</h2><TextField autoFocus label={language==='es'?'Nombre':'Name'} value={name} onChange={event=>setName(event.target.value)} required/><FormControl><InputLabel id="edit-kind-label">{selectLabel}</InputLabel><Select labelId="edit-kind-label" label={selectLabel} value={value} onChange={event=>setValue(event.target.value)} MenuProps={{disablePortal:true}}>{(accounts?[['cash','Cash'],['bank','Bank'],['wallet','Wallet']]:[['expense',language==='es'?'Egreso':'Expense'],['income',language==='es'?'Ingreso':'Income'],['both',language==='es'?'Ambos':'Both']]).map(([optionValue,optionLabel])=><MenuItem key={optionValue} value={optionValue}>{optionLabel}</MenuItem>)}</Select></FormControl><div className="modal-actions"><Button variant="outlined" onClick={onClose}>{language==='es'?'Cancelar':'Cancel'}</Button><Button type="submit" variant="contained">{language==='es'?'Guardar cambios':'Save changes'}</Button></div></form></div>}
function PasswordChangeModal({token,language,forced,open,onClose,onDone,onError}:{token:string;language:Lang;forced:boolean;open:boolean;onClose:()=>void;onDone:()=>void;onError:(message:string)=>void}){const [current,setCurrent]=useState('');const [next,setNext]=useState('');const [confirm,setConfirm]=useState('');const [saving,setSaving]=useState(false);if(!open)return null;const submit=async(event:FormEvent)=>{event.preventDefault();if(next.length<12||next!==confirm){onError(language==='es'?'La nueva clave debe tener 12 caracteres y coincidir.':'The new password must have 12 characters and match.');return;}setSaving(true);try{await request('/v1/auth/change-password',token,'POST',{currentPassword:current,newPassword:next});setCurrent('');setNext('');setConfirm('');onDone();}catch(error){onError((error as Error).message);}finally{setSaving(false);}};return <div className="modal-backdrop"><form className="modal password-change-modal" role="dialog" aria-modal="true" aria-labelledby="password-modal-title" onSubmit={submit}><h2 id="password-modal-title">{language==='es'?'Cambiar contraseña':'Change password'}</h2>{forced&&<p className="notice">{language==='es'?'Un administrador solicitó que actualices tu contraseña antes de continuar.':'An administrator requires you to update your password before continuing.'}</p>}<input type="password" value={current} onChange={event=>setCurrent(event.target.value)} placeholder={language==='es'?'Contraseña actual':'Current password'} required/><input type="password" value={next} onChange={event=>setNext(event.target.value)} placeholder={language==='es'?'Nueva contraseña (12+ caracteres)':'New password (12+ characters)'} required/><input type="password" value={confirm} onChange={event=>setConfirm(event.target.value)} placeholder={language==='es'?'Repetir nueva contraseña':'Repeat new password'} required/><div className="modal-actions">{!forced&&<Button variant="outlined" onClick={onClose}>{language==='es'?'Cancelar':'Cancel'}</Button>}<Button type="submit" variant="contained" disabled={saving}>{language==='es'?'Guardar contraseña':'Save password'}</Button></div></form></div>}
function CsvActions({onTemplate,onImport,onExport}:{onTemplate:()=>void;onImport:(file:File)=>void;onExport?:()=>void}){const spanish=document.documentElement.lang!=='en';const selectFile=(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(file)onImport(file);event.target.value='';};return <div className="csv-actions"><button className="secondary" onClick={onTemplate}>{spanish?'Descargar plantilla':'Download template'}</button><label className="secondary file-action">{spanish?'Importar CSV':'Import CSV'}<input type="file" accept=".csv,text/csv" onChange={selectFile}/></label>{onExport&&<button className="secondary" onClick={onExport}>{spanish?'Exportar CSV':'Export CSV'}</button>}</div>;}
function Management({t,kind,items,submit,edit,deactivate,csv,onAccountAction,onCategoryAction,onBulk}:{t:Copy;kind:'accounts'|'categories';items:(Account|Category)[];submit:(e:FormEvent<HTMLFormElement>)=>void;edit:(v:Account|Category)=>void;deactivate:(id:string)=>void;csv?:{onTemplate:()=>void;onImport:(file:File)=>void};onAccountAction?:(id:string,action:'activate'|'deactivate'|'delete')=>void;onCategoryAction?:(id:string,action:'activate'|'deactivate'|'delete')=>void;onBulk?:(ids:string[],action:'activate'|'deactivate')=>void}) {
  const accounts = kind === 'accounts';
  const [selected,setSelected]=useState<string[]>([]),[usage,setUsage]=useState('all');
  const usageCount=(item:Account|Category)=>'usageCount' in item?item.usageCount:0;
  const shown=items.filter(item=>!accounts?(usage==='all'||(usage==='used'&&usageCount(item)>0)||(usage==='unused'&&usageCount(item)===0)):true);
  const toggle=(id:string)=>setSelected(current=>current.includes(id)?current.filter(value=>value!==id):[...current,id]);
  const bulk=(action:'activate'|'deactivate')=>{const ids=shown.filter(item=>selected.includes(item.id)&&item.active===(action==='deactivate')).filter(item=>accounts||usageCount(item)===0).map(item=>item.id);onBulk?.(ids,action);setSelected([]);};
  const spanish=t.active==='Activo';
  return <Card className="material-card" elevation={0}><CardContent><Stack spacing={3}><Box><Typography component="h2" variant="h5">{accounts?t.accounts:t.categories}</Typography><Typography variant="body2" color="text.secondary">{accounts?(spanish?'Administrá las cuentas disponibles para registrar movimientos.':'Manage the accounts available to record movements.'):(spanish?'Organizá los movimientos con categorías reutilizables.':'Organize movements with reusable categories.')}</Typography></Box><form className="material-form" onSubmit={submit}><TextField name="name" required label={accounts?t.accountName:t.categoryName}/><FormControl required><InputLabel id={`${kind}-kind-label`}>{accounts?t.type:(spanish?'Tipo':'Type')}</InputLabel><Select labelId={`${kind}-kind-label`} label={accounts?t.type:(spanish?'Tipo':'Type')} name={accounts?'type':'direction'} defaultValue={accounts?'cash':'expense'} MenuProps={{disablePortal:false}}>{(accounts?[['cash','Cash'],['bank','Bank'],['wallet','Wallet']]:[['expense',t.expense],['income',t.income],['both',spanish?'Ambos':'Both']]).map(([optionValue,optionLabel])=><MenuItem key={optionValue} value={optionValue}>{optionLabel}</MenuItem>)}</Select></FormControl><Button type="submit" variant="contained" startIcon={<AddOutlined/>}>{t.add}</Button></form>{csv&&<CsvActions {...csv}/>} {!accounts&&<FormControl size="small" className="usage-filter"><InputLabel id="usage-label">{spanish?'Uso':'Usage'}</InputLabel><Select labelId="usage-label" label={spanish?'Uso':'Usage'} value={usage} onChange={event=>setUsage(event.target.value)} MenuProps={{disablePortal:true}}><MenuItem value="all">{spanish?'Todas':'All'}</MenuItem><MenuItem value="used">{spanish?'Con movimientos':'With movements'}</MenuItem><MenuItem value="unused">{spanish?'Sin movimientos':'Without movements'}</MenuItem></Select></FormControl>}<Stack direction={{xs:'column',sm:'row'}} spacing={1} alignItems={{sm:'center'}}><Button variant="outlined" disabled={!selected.some(id=>items.find(item=>item.id===id)?.active===false)} onClick={()=>bulk('activate')}>{spanish?'Activar seleccionadas':'Activate selected'}</Button><Button variant="outlined" disabled={!selected.some(id=>{const item=items.find(value=>value.id===id);return item?.active&&(accounts||item.usageCount===0);})} onClick={()=>bulk('deactivate')}>{spanish?'Desactivar seleccionadas':'Deactivate selected'}</Button>{!accounts&&<Typography variant="caption" color="text.secondary">{spanish?'Las categorías con movimientos se desactivan individualmente para elegir su migración.':'Categories with movements are deactivated individually to choose their migration.'}</Typography>}</Stack>{shown.length?<List disablePadding className="material-list">{shown.map(item=><ListItem key={item.id} className={!item.active?'voided-row':''} secondaryAction={<Stack direction="row" spacing={1}>{item.active?<><Button size="small" variant="text" onClick={()=>edit(item)}>{t.edit}</Button><Button size="small" variant="outlined" onClick={()=>accounts&&onAccountAction?onAccountAction(item.id,'deactivate'):onCategoryAction?.(item.id,'deactivate')}>{t.deactivate}</Button></>:accounts&&onAccountAction?<><Button size="small" variant="outlined" onClick={()=>onAccountAction(item.id,'activate')}>{languageLabel(t,'activate')}</Button><Button size="small" color="error" variant="text" onClick={()=>onAccountAction(item.id,'delete')}>{languageLabel(t,'delete')}</Button></>:<Button size="small" variant="outlined" onClick={()=>onCategoryAction?.(item.id,'activate')}>{languageLabel(t,'activate')}</Button>}</Stack>}><Checkbox edge="start" checked={selected.includes(item.id)} onChange={()=>toggle(item.id)} inputProps={{'aria-label':item.name}}/><ListItemText primary={<Stack direction="row" spacing={1} alignItems="center"><Typography>{item.name}</Typography><Chip size="small" variant="outlined" label={'type' in item?item.type:item.direction}/></Stack>} secondary={`${'usageCount' in item?`${item.usageCount} ${spanish?'movimientos':'movements'} · `:''}${item.active?t.active:(spanish?'inactiva':'inactive')}`}/></ListItem>)}</List>:<Typography color="text.secondary">{accounts?t.noAccounts:t.noCategories}</Typography>}</Stack></CardContent></Card>;
}
function languageLabel(t:Copy, action:'activate'|'delete'){return action==='activate'?(t.active==='Activo'?'Activar':'Activate'):(t.active==='Activo'?'Eliminar':'Delete');}
function UserManagement({users,currentUserId,submit,onAction,onBulk,onResetPassword,language}:{users:User[];currentUserId:string;submit:(event:FormEvent<HTMLFormElement>)=>void;onAction:(id:string,action:'activate'|'deactivate'|'delete')=>void;onBulk:(ids:string[],action:'activate'|'deactivate')=>void;onResetPassword:(id:string)=>void;language:Lang}){const [selected,setSelected]=useState<string[]>([]);const [password,setPassword]=useState('');const [generated,setGenerated]=useState(false);const toggle=(id:string)=>setSelected(current=>current.includes(id)?current.filter(value=>value!==id):[...current,id]);const bulk=(action:'activate'|'deactivate')=>{onBulk(selected.filter(id=>users.find(user=>user.id===id)?.active===(action==='deactivate')),action);setSelected([]);};const roleLabel=(role:string)=>({administrator:language==='es'?'Administrador':'Administrator',manager:language==='es'?'Gestor':'Manager',operator:language==='es'?'Operador':'Operator'}[role]??role);const createSubmit=(event:FormEvent<HTMLFormElement>)=>{submit(event);setPassword('');setGenerated(false);};const generate=()=>{const value=generatePassword();setPassword(value);setGenerated(true);void copySecret(value);};return <section className="card"><h2>{language==='es'?'Usuarios':'Users'}</h2><form className="user-create-form" onSubmit={createSubmit}><input name="displayName" placeholder={language==='es'?'Nombre':'Name'} required/><input className="user-email" name="email" type="email" placeholder={language==='es'?'Correo electrónico':'Email'} required/><div className="password-field"><input name="password" type={generated?'text':'password'} placeholder={language==='es'?'Contraseña (12+ caracteres)':'Password (12+ characters)'} value={password} onChange={event=>{setPassword(event.target.value);setGenerated(false);}} required/><input type="hidden" name="forcePasswordChange" value={generated?'true':'false'}/><div className="password-actions"><button type="button" className="secondary" onClick={generate}>{language==='es'?'Generar':'Generate'}</button>{generated&&<button type="button" className="secondary" onClick={()=>void copySecret(password)}>{language==='es'?'Copiar':'Copy'}</button>}{generated&&<button type="button" className="secondary" onClick={()=>downloadCSV(`fluxeando-password-${exportTimestamp()}.csv`,`display_name,email,password,generated_at\n${csvCell('Nuevo usuario')},,,${csvCell(new Date().toISOString())}\n`)}>{language==='es'?'Exportar CSV':'Export CSV'}</button>}</div></div><FormControl className="user-role-select" size="small" required><InputLabel id="user-role-label">{language==='es'?'Rol':'Role'}</InputLabel><Select labelId="user-role-label" label={language==='es'?'Rol':'Role'} name="role" defaultValue="operator" MenuProps={{disablePortal:false}}><MenuItem value="operator">{language==='es'?'Operador':'Operator'}</MenuItem><MenuItem value="manager">{language==='es'?'Gestor':'Manager'}</MenuItem><MenuItem value="administrator">{language==='es'?'Administrador':'Administrator'}</MenuItem></Select></FormControl><button>{language==='es'?'Crear usuario':'Create user'}</button></form><small className="password-hint">{language==='es'?'Las claves generadas se copian al portapapeles y requieren cambio en el próximo ingreso.':'Generated passwords are copied to the clipboard and require a change at next sign in.'}</small><div className="bulk-actions"><button className="secondary" disabled={!selected.some(id=>users.find(user=>user.id===id)?.active===false)} onClick={()=>bulk('activate')}>{language==='es'?'Activar seleccionados':'Activate selected'}</button><button className="secondary" disabled={!selected.some(id=>users.find(user=>user.id===id)?.active===true)} onClick={()=>bulk('deactivate')}>{language==='es'?'Desactivar seleccionados':'Deactivate selected'}</button></div><List className="material-list user-list">{users.map(item=>{const isCurrent=item.id===currentUserId;return <ListItem key={item.id} className={item.active?'':'voided-row'} secondaryAction={!isCurrent?<Stack direction="row" spacing={1}>{item.active?<Button variant="text" onClick={()=>onAction(item.id,'deactivate')}>{language==='es'?'Desactivar':'Deactivate'}</Button>:<Button variant="text" onClick={()=>onAction(item.id,'activate')}>{language==='es'?'Activar':'Activate'}</Button>}<Button variant="text" onClick={()=>onResetPassword(item.id)}>{language==='es'?'Restablecer clave':'Reset password'}</Button><Button variant="text" color="error" onClick={()=>onAction(item.id,'delete')}>{language==='es'?'Eliminar':'Delete'}</Button></Stack>:undefined}>{!isCurrent&&<Checkbox edge="start" checked={selected.includes(item.id)} onChange={()=>toggle(item.id)} inputProps={{'aria-label':item.displayName}}/>}<ListItemText primary={<Stack direction="row" spacing={1} alignItems="center" useFlexGap flexWrap="wrap"><strong>{item.displayName}</strong><Chip size="small" variant="outlined" label={roleLabel(item.role)}/>{isCurrent&&<Chip size="small" label={language==='es'?'Tu usuario':'Your user'}/>}<Chip size="small" color={item.active?'success':'default'} variant={item.active?'outlined':'filled'} label={item.active?(language==='es'?'Activo':'Active'):(language==='es'?'Inactivo':'Inactive')}/>{item.mustChangePassword&&<Chip size="small" color="warning" label={language==='es'?'Debe cambiar clave':'Must change password'}/>}</Stack>} secondary={item.email}/></ListItem>;})}</List></section>;}
function DeletionRequests({requests,resolve,cancel,canResolve,language}:{requests:DeletionRequest[];resolve:(id:string,decision:'approve'|'reject')=>void;cancel:(id:string)=>void;canResolve:boolean;language:Lang}){const pending=requests.filter(item=>item.status==='pending'),completed=requests.filter(item=>item.status!=='pending');const list=(items:DeletionRequest[],actions:boolean)=><ul className="management-list">{items.map(item=><li key={item.id}><span><strong>{language==='es'?'Movimiento':'Movement'} </strong><small>{item.entityId} · {item.createdAt}</small><br/><small>{language==='es'?'Solicitante':'Requested by'}: {item.requestedByName} · {language==='es'?'Motivo':'Reason'}: {item.reason}</small>{item.resolvedAt&&<><br/><small>{language==='es'?'Tramitada':'Processed'}: {item.status} · {item.resolvedAt}</small></>}</span>{actions&&<span>{canResolve?<><button onClick={()=>resolve(item.id,'approve')}>{language==='es'?'Aprobar':'Approve'}</button><button className="secondary" onClick={()=>resolve(item.id,'reject')}>{language==='es'?'Rechazar':'Reject'}</button></>:<button className="secondary" onClick={()=>cancel(item.id)}>{language==='es'?'Cancelar solicitud':'Cancel request'}</button>}</span>}</li>)}</ul>;return <section className="card"><h2>{language==='es'?'Solicitudes de anulación':'Void requests'}</h2>{pending.length?list(pending,true):<p className="items">{language==='es'?'No hay solicitudes pendientes.':'No pending requests.'}</p>}{completed.length>0&&<details><summary>{language==='es'?`Tramitadas (${completed.length})`:`Processed (${completed.length})`}</summary>{list(completed,false)}</details>}</section>;}
function traceJSON(value:string){if(!value||value==='null')return '—';try{return JSON.stringify(JSON.parse(value),null,2);}catch{return value;}}
function AuditTrail({events,language}:{events:AuditEvent[];language:Lang}){const [search,setSearch]=useState('');const [entity,setEntity]=useState('');const [correlation,setCorrelation]=useState('');const entities=[...new Set(events.map(event=>event.entityType))].sort();const visible=events.filter(event=>{const text=`${event.action} ${event.actorName} ${event.entityType} ${event.entityId} ${event.correlationId}`.toLowerCase();return (!search||text.includes(search.toLowerCase()))&&(!entity||event.entityType===entity)&&(!correlation||event.correlationId===correlation);});return <section className="card audit-trail"><div className="section-head"><div><h2>{language==='es'?'Auditoría':'Audit trail'}</h2><p className="items">{language==='es'?'Trazabilidad inmutable de cada acción registrada.':'Immutable trace of every recorded action.'}</p></div><strong>{visible.length} / {events.length}</strong></div><div className="audit-filters"><TextField size="small" value={search} onChange={event=>setSearch(event.target.value)} label={language==='es'?'Buscar por acción, usuario o ID':'Search action, user or ID'}/><FormControl size="small"><InputLabel id="audit-entity-label">{language==='es'?'Entidad':'Entity'}</InputLabel><Select labelId="audit-entity-label" label={language==='es'?'Entidad':'Entity'} value={entity} onChange={event=>setEntity(event.target.value)}><MenuItem value="">{language==='es'?'Todas las entidades':'All entities'}</MenuItem>{entities.map(value=><MenuItem key={value} value={value}>{value}</MenuItem>)}</Select></FormControl><TextField size="small" value={correlation} onChange={event=>setCorrelation(event.target.value)} label={language==='es'?'ID de correlación':'Correlation ID'}/></div>{visible.length?<ol className="audit-list">{visible.map(event=><li key={event.id}><details><summary><time>{new Date(event.createdAt).toLocaleString(language==='es'?'es-AR':'en-US')}</time><strong>{event.action.replaceAll('_',' ')}</strong><span>{event.actorName}</span><small>{event.entityType} · {event.entityId}</small></summary><div className="audit-details"><dl><dt>{language==='es'?'Actor':'Actor'}</dt><dd>{event.actorName} <code>{event.actorId||'system'}</code></dd><dt>{language==='es'?'Entidad':'Entity'}</dt><dd>{event.entityType} <code>{event.entityId}</code></dd><dt>{language==='es'?'Correlación':'Correlation'}</dt><dd><code>{event.correlationId}</code></dd><dt>{language==='es'?'Evento':'Event'}</dt><dd><code>{event.id}</code></dd></dl><div className="audit-payload"><section><h3>{language==='es'?'Antes':'Before'}</h3><pre>{traceJSON(event.before)}</pre></section><section><h3>{language==='es'?'Después':'After'}</h3><pre>{traceJSON(event.after)}</pre></section></div></div></details></li>)}</ol>:<p className="items">{language==='es'?'No hay eventos para esos filtros.':'No events match these filters.'}</p>}</section>;}
function Analytics({t,movements,accounts,hidden}:{t:Copy;movements:Movement[];accounts:Account[];hidden:boolean;onToggleHidden:(value:boolean)=>void}){
  const [year,setYear]=useState(String(new Date().getFullYear()));
  const [currency,setCurrency]=useState('');
  const [accountId,setAccountId]=useState('all');
  const [selectedMonth,setSelectedMonth]=useState('');
  const [selectedDate,setSelectedDate]=useState<string|null>(null);
  const active=useMemo(()=>movements.filter(m=>m.status==='active'&&m.occurredOn.startsWith(year)&&(accountId==='all'||m.accountId===accountId)),[movements,year,accountId]);
  const currencies=useMemo(()=>[...new Set(active.map(m=>m.currency))].sort(),[active]);
  useEffect(()=>{if(!currencies.includes(currency))setCurrency(currencies[0]??'');},[currencies,currency]);
  const scoped=active.filter(m=>m.currency===currency);
  const selectedAccount=accountId==='all'?'Consolidado (todas las cuentas)':(accounts.find(a=>a.id===accountId)?.name??'Cuenta');
  const months=useMemo(()=>Array.from({length:12},(_,index)=>{const value=`${year}-${String(index+1).padStart(2,'0')}`;const items=scoped.filter(m=>m.occurredOn.startsWith(value));return {value,label:new Date(2000,index,1).toLocaleDateString('es-AR',{month:'short'}).replace('.',''),income:items.filter(m=>m.direction==='income').reduce((sum,m)=>sum+m.amountMinor,0),expense:items.filter(m=>m.direction==='expense').reduce((sum,m)=>sum+m.amountMinor,0)};}),[scoped,year]);
  useEffect(()=>{if(!months.some(month=>month.value===selectedMonth))setSelectedMonth(months.find(month=>month.income||month.expense)?.value??months[0]?.value??'');},[months,selectedMonth]);
  const days=useMemo(()=>{const grouped=new Map<string,Movement[]>();scoped.filter(m=>m.occurredOn.startsWith(selectedMonth)).forEach(m=>grouped.set(m.occurredOn,[...(grouped.get(m.occurredOn)??[]),m]));return [...grouped.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([date,items])=>({date,items,income:items.filter(m=>m.direction==='income').reduce((sum,m)=>sum+m.amountMinor,0),expense:items.filter(m=>m.direction==='expense').reduce((sum,m)=>sum+m.amountMinor,0)}));},[scoped,selectedMonth]);
  const selected=days.find(day=>day.date===selectedDate)??null;
  const totalIncome=scoped.filter(m=>m.direction==='income').reduce((sum,m)=>sum+m.amountMinor,0);
  const totalExpense=scoped.filter(m=>m.direction==='expense').reduce((sum,m)=>sum+m.amountMinor,0);
  const monthlyMaximum=Math.max(...months.flatMap(month=>[month.income,month.expense]),1);
  const maximum=Math.max(...days.flatMap(day=>[day.income,day.expense]),1);
  const summary=(day:typeof days[number])=>day.items.length?`${day.items.length} movimientos · ${[...new Set(day.items.map(m=>m.accountName||'Cuenta sin nombre'))].join(', ')}`:'Sin movimientos';
  if(!active.length)return <section className="card"><div className="section-head"><h2>{t.analytics}</h2><label>{t.year} <YearPicker year={year} onChange={setYear}/></label></div><p>{t.noData}</p></section>;
  return <section className="card analytics-card"><div className="section-head"><div><h2>{t.analytics}</h2><p className="items">Ingresos, egresos y categorías a partir de tus movimientos.</p></div><div className="analytics-controls"><label>Cuenta<select value={accountId} onChange={event=>setAccountId(event.target.value)}><option value="all">Consolidado (todas)</option>{accounts.filter(account=>account.active).map(account=><option key={account.id} value={account.id}>{account.name}</option>)}</select></label><label>{t.year}<YearPicker year={year} onChange={setYear}/></label><label>{t.currency}<select value={currency} onChange={event=>setCurrency(event.target.value)}>{currencies.map(value=><option key={value}>{value}</option>)}</select></label><label>Mes<select value={selectedMonth} onChange={event=>{setSelectedMonth(event.target.value);setSelectedDate(null);}}>{months.map(month=><option key={month.value} value={month.value}>{month.label}</option>)}</select></label></div></div><p className="analytics-scope">Resumen de: <strong>{selectedAccount}</strong></p><div className="analytics-summary"><strong>Ingresos del año <Amount amount={totalIncome} currency={currency} hidden={hidden}/></strong><strong>Egresos del año <Amount amount={totalExpense} currency={currency} hidden={hidden}/></strong><strong>Balance <Amount amount={totalIncome-totalExpense} currency={currency} hidden={hidden}/></strong></div><div className="analytics-chart-block daily-detail"><div className="chart-title"><div><h3>Movimientos por día</h3><span>Hover: resumen. Clic: detalle y cuentas relacionadas.</span></div><div className="chart-legend"><span><i className="legend-income"/>Ingresos</span><span><i className="legend-expense"/>Egresos</span></div></div><div className="daily-chart">{days.map(day=><button className="daily-column" key={day.date} title={summary(day)} onClick={()=>setSelectedDate(day.date)} aria-label={`Ver detalle del ${day.date}`}><span className="daily-bars"><i className="bar-income" style={{height:`${day.income/maximum*100}%`}}/><i className="bar-expense" style={{height:`${day.expense/maximum*100}%`}}/></span><small>{day.date.slice(8,10)}</small></button>)}</div></div><Dialog open={Boolean(selected)} onClose={()=>setSelectedDate(null)} fullWidth maxWidth="sm"><DialogTitle>Detalle del {selected?.date}</DialogTitle><DialogContent>{selected&&<><Typography variant="body2" color="text.secondary">Sumarización de cuentas: {[...new Set(selected.items.map(m=>m.accountName||'Cuenta sin nombre'))].join(', ')}</Typography><List dense>{selected.items.map(m=><ListItem key={m.id}><ListItemText primary={`${m.direction==='income'?'Ingreso':'Egreso'} · ${m.description||m.categoryName||'Sin detalle'}`} secondary={`${m.accountName||'Cuenta sin nombre'} · ${m.categoryName||'Sin categoría'} · ${hidden?'••••':(m.amountMinor/100).toLocaleString('es-AR',{minimumFractionDigits:2})} ${m.currency}`}/></ListItem>)}</List></>}</DialogContent><DialogActions><Button onClick={()=>setSelectedDate(null)}>Cerrar</Button></DialogActions></Dialog></section>;
}
function AppearanceSettings({language,colorMode,accent,onAccentChange,typography,onTypographyChange}:{language:Lang;colorMode:ColorMode;accent:AccentPalette;onAccentChange:(value:AccentPalette)=>void;typography:TypographyFamily;onTypographyChange:(value:TypographyFamily)=>void}){const title=language==='es'?'Apariencia':'Appearance';return <Card className="material-card settings-card" elevation={0}><CardContent><details className="settings-section"><summary><span><Typography component="h2" variant="h5">{title}</Typography><Typography color="text.secondary">{language==='es'?'Tema, paleta y contraste visual.':'Theme, palette, and visual contrast.'}</Typography></span><span className="settings-chevron" aria-hidden="true">⌄</span></summary><div className="settings-section-content"><Typography color="text.secondary">{language==='es'?'Elegí una paleta completa para el modo actual.':'Choose a complete palette for the current mode.'}</Typography><Box><Typography variant="subtitle1">{language==='es'?'Paleta para el modo actual':'Palette for the current mode'} · {colorMode==='light'?(language==='es'?'Claro':'Light'):(language==='es'?'Oscuro':'Dark')}</Typography><div className="palette-grid">{(Object.keys(accentPalettes) as AccentPalette[]).map(key=>{const palette=accentPalettes[key],selected=accent===key,swatches=colorMode==='dark'?palette.darkSwatches:palette.lightSwatches;return <button key={key} className={`palette-option ${selected?'selected':''}`} onClick={()=>onAccentChange(key)} aria-pressed={selected}><span className="palette-swatch-set">{swatches.map(color=><i key={color} style={{backgroundColor:color}}/>)}</span><span><strong>{palette.name[language]}</strong><small>{selected?(language==='es'?'Seleccionada':'Selected'):(language==='es'?'Seleccionar':'Select')}</small></span></button>;})}</div></Box><Box className="typography-settings"><Typography variant="subtitle1">{language==='es'?'Tipografía de la interfaz':'Interface typography'}</Typography><Typography variant="body2" color="text.secondary">{language==='es'?'La selección se aplica a títulos, texto y controles.':'The selection applies to headings, text, and controls.'}</Typography><div className="typography-grid">{(Object.keys(typographyFamilies) as TypographyFamily[]).map(key=>{const family=typographyFamilies[key],selected=typography===key;return <button key={key} className={`typography-option ${selected?'selected':''}`} onClick={()=>onTypographyChange(key)} aria-pressed={selected} style={{fontFamily:family.stack}}><span className="typography-sample">Ag</span><span><strong>{family.name[language]}</strong><small>{family.description[language]}</small></span></button>;})}</div></Box><Typography variant="caption" color="text.secondary">{language==='es'?'La elección se guarda sólo en este dispositivo.':'Your selection is stored only on this device.'}</Typography></div></details></CardContent></Card>}
function Root(){const [colorMode,setColorMode]=useState<ColorMode>(()=>localStorage.getItem('fluxeando-color-mode')==='dark'?'dark':'light');const [accents,setAccents]=useState<Record<ColorMode,AccentPalette>>(()=>({light:(localStorage.getItem('fluxeando-accent-light') as AccentPalette)||'graphite',dark:(localStorage.getItem('fluxeando-accent-dark') as AccentPalette)||'graphite'}));const [typography,setTypography]=useState<TypographyFamily>(()=>(localStorage.getItem('fluxeando-typography') as TypographyFamily)||'current');const [allowLogger,setAllowLogger]=useState(()=>localStorage.getItem('fluxeando-allow-logger')==='true');const accent=accents[colorMode];const setAccent=(value:AccentPalette)=>setAccents(current=>({...current,[colorMode]:value}));const theme=useMemo(()=>cashflowTheme(colorMode,accent,typography),[colorMode,accent,typography]);useEffect(()=>{const variables=materialVariables(materialSchemes[accent][colorMode]);Object.entries(variables).forEach(([name,value])=>document.documentElement.style.setProperty(name,String(value)));document.documentElement.style.setProperty('--ui-font-family',typographyFamilies[typography].stack);localStorage.setItem('fluxeando-color-mode',colorMode);localStorage.setItem('fluxeando-accent-light',accents.light);localStorage.setItem('fluxeando-accent-dark',accents.dark);localStorage.setItem('fluxeando-typography',typography);localStorage.setItem('fluxeando-allow-logger',String(allowLogger));document.body.dataset.colorMode=colorMode;document.body.dataset.accent=accent;document.body.dataset.typography=typography;},[colorMode,accent,accents,typography,allowLogger]);return <ThemeProvider theme={theme}><CssBaseline/><ErrorBoundary><App colorMode={colorMode} setColorMode={setColorMode} accent={accent} setAccent={setAccent} typography={typography} setTypography={setTypography} allowLogger={allowLogger} setAllowLogger={setAllowLogger}/></ErrorBoundary></ThemeProvider>;}
createRoot(document.getElementById('root')!).render(<Root/>);
